"use client";
/* Crumb, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Crumb(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("crumb"); }, []);
  return React.createElement("piix-pal", { "pal": "crumb", ...piixAttrs(props) });
}

export default Crumb;
